"""Personal expense manager.

This is the code that "already exists." It works, it's used daily, and
it doesn't have a single test. Save it as-is, without changing anything,
as gastos.py inside the gastos-cli folder.
"""

import json
import os
from datetime import date


def ruta_fichero():
    """Where expenses are saved.

    Comes from an environment variable (a setting that lives outside
    the code, in the system). That way tests can point to a disposable
    file without ever touching your real data.
    """
    return os.environ.get("GASTOS_FICHERO", "gastos.json")


def cargar():
    """Reads the list of expenses from disk. If there's no file, an empty list."""
    ruta = ruta_fichero()
    if not os.path.exists(ruta):
        return []
    with open(ruta, "r", encoding="utf-8") as f:
        return json.load(f)


def guardar(gastos):
    """Writes the whole list to disk, in JSON format."""
    with open(ruta_fichero(), "w", encoding="utf-8") as f:
        json.dump(gastos, f, ensure_ascii=False, indent=2)


def anadir(concepto, importe, fecha=None):
    """Records a new expense and returns the expense created."""
    if importe <= 0:
        raise ValueError("The amount must be greater than zero")
    gasto = {
        "concepto": concepto.strip(),
        "importe": round(float(importe), 2),
        "fecha": fecha or date.today().isoformat(),
    }
    gastos = cargar()
    gastos.append(gasto)
    guardar(gastos)
    return gasto


def entre_fechas(gastos, desde, hasta):
    """Expenses with a date between desde and hasta, both days included.

    Dates are text like "2026-03-15". Written that way, comparing
    strings is the same as comparing dates.
    """
    return [g for g in gastos if desde <= g["fecha"] < hasta]


def total(gastos):
    """Sum of the amounts in a list of expenses."""
    return round(sum(g["importe"] for g in gastos), 2)


def media_diaria(gastos):
    """Average spend per day on which there was at least one expense."""
    dias = {g["fecha"] for g in gastos}
    return round(total(gastos) / len(dias), 2)


def buscar(gastos, texto):
    """Expenses whose description contains the searched text."""
    return [g for g in gastos if texto in g["concepto"]]


def con_iva(importe, tipo=21):
    """Adds VAT to an amount. Defaults to the general 21% rate."""
    return round(importe * (1 + tipo / 100), 2)

"""gastos.py with the three bugs fixed.

Replace the entire contents of gastos.py with this. The changes are
three and are marked with the comment FIX.
"""

import json
import os
from datetime import date


def ruta_fichero():
    """Where expenses are saved. Comes from an environment variable."""
    return os.environ.get("GASTOS_FICHERO", "gastos.json")


def cargar():
    """Reads the list of expenses from disk. If there's no file, an empty list."""
    ruta = ruta_fichero()
    if not os.path.exists(ruta):
        return []
    with open(ruta, "r", encoding="utf-8") as f:
        return json.load(f)


def guardar(gastos):
    """Writes the whole list to disk, in JSON format."""
    with open(ruta_fichero(), "w", encoding="utf-8") as f:
        json.dump(gastos, f, ensure_ascii=False, indent=2)


def anadir(concepto, importe, fecha=None):
    """Records a new expense and returns the expense created."""
    if importe <= 0:
        raise ValueError("The amount must be greater than zero")
    gasto = {
        "concepto": concepto.strip(),
        "importe": round(float(importe), 2),
        "fecha": fecha or date.today().isoformat(),
    }
    gastos = cargar()
    gastos.append(gasto)
    guardar(gastos)
    return gasto


def entre_fechas(gastos, desde, hasta):
    """Expenses with a date between desde and hasta, both days included."""
    # FIX 1: it used to say  < hasta  and ate the last day of the month.
    # With March 31st left out, March's total came out 18.90 EUR short.
    return [g for g in gastos if desde <= g["fecha"] <= hasta]


def total(gastos):
    """Sum of the amounts in a list of expenses."""
    return round(sum(g["importe"] for g in gastos), 2)


def media_diaria(gastos):
    """Average spend per day on which there was at least one expense."""
    dias = {g["fecha"] for g in gastos}
    # FIX 2: without this, dividing by 0 days crashed the program
    # on the very first day of use, when there were no expenses yet.
    if not dias:
        return 0.0
    return round(total(gastos) / len(dias), 2)


def buscar(gastos, texto):
    """Expenses whose description contains the searched text."""
    # FIX 3: it used to be case-sensitive, so searching "mercadona"
    # didn't find "Mercadona". Now both are compared lowercased.
    texto = texto.lower()
    return [g for g in gastos if texto in g["concepto"].lower()]


def con_iva(importe, tipo=21):
    """Adds VAT to an amount. Defaults to the general 21% rate."""
    return round(importe * (1 + tipo / 100), 2)


